(async () => {
  const { accessSync, constants } = await import('node:fs');
  const inputPath = process.env.INPUT_PATH;
  const outputPath = process.env.OUTPUT_PATH;
  if (!inputPath) throw new Error('Missing INPUT_PATH');
  if (!outputPath) throw new Error('Missing OUTPUT_PATH');
  try { accessSync(inputPath, constants.R_OK); } catch { throw new Error('Input file not accessible'); }
  globalThis.inputPath = inputPath;
  globalThis.outputPath = outputPath;
})();

(async () => {
  const { readFileSync, writeFileSync } = await import('node:fs');
  const yamlModRaw = await import('js-yaml');
  const yamlMod = yamlModRaw.default || yamlModRaw;
  const yamlContent = readFileSync(globalThis.inputPath, 'utf8');
  const data = typeof yamlMod.safeLoad === 'function' ? yamlMod.safeLoad(yamlContent) : yamlMod.load(yamlContent);
  const jsonStr = JSON.stringify(data, null, 2);
  writeFileSync(globalThis.outputPath, jsonStr, 'utf8');
  globalThis.resultPath = globalThis.outputPath;
})();
